html:
{%- set inst = get_institution_details() -%}
{%- set c = doc.certificate or {} -%}
<style>
	.bc { font-family: "Times New Roman", Times, "Liberation Serif", "DejaVu Serif", Georgia, serif; color: #111; font-size: 13pt; line-height: 1.65; }
	.bc table { width: 100%; border-collapse: collapse; }
	.bc-head td { vertical-align: middle; padding: 0 0 10px 0; }
	.bc-head .side { width: 96px; }
	.bc-head .side img { max-width: 88px; max-height: 88px; }
	.bc-inst { text-align: center; }
	.bc-inst .n { font-size: 16pt; font-weight: bold; color: #1f3a5f; text-transform: uppercase; letter-spacing: 0.5px; line-height: 1.25; }
	.bc-inst .a { font-size: 10pt; color: #333; line-height: 1.4; margin-top: 4px; }
	.bc-inst .c { font-size: 9.5pt; color: #444; line-height: 1.4; }
	.bc-rule { border-top: 2.5px solid #1f3a5f; border-bottom: 1px solid #1f3a5f; height: 2px; }
	.bc-meta { margin-top: 18px; font-size: 11.5pt; }
	.bc-meta td.r { text-align: right; }
	.bc-title { text-align: center; font-size: 18pt; font-weight: bold; letter-spacing: 4px; margin: 34px 0 26px 0; }
	.bc-title span { border-bottom: 1.5px solid #111; padding-bottom: 2px; }
	.bc-body p { text-align: justify; text-indent: 40px; margin: 0 0 16px 0; }
	.bc-body .nw { white-space: nowrap; }
	.bc-foot { margin-top: 52px; }
	.bc-foot td { vertical-align: bottom; }
	.bc-qr { width: 50%; }
	.bc-qr img { width: 108px; height: 108px; }
	.bc-qr .t { font-size: 8.5pt; color: #333; line-height: 1.35; margin-top: 4px; width: 250px; }
	.bc-qr .code { font-family: "Courier New", Courier, monospace; font-weight: bold; letter-spacing: 0.5px; }
	.bc-sign { text-align: right; }
	.bc-sign .s { display: inline-block; text-align: center; min-width: 230px; font-size: 12pt; line-height: 1.4; }
	.bc-sign .gap { height: 64px; }
	.bc-sign .who { border-top: 1px solid #111; padding-top: 4px; font-weight: bold; }
	.bc-note { margin-top: 40px; font-size: 8.5pt; color: #555; border-top: 1px solid #bbb; padding-top: 6px; text-align: center; line-height: 1.4; }
	.bc-draft { border: 2px dashed #b3261e; color: #b3261e; padding: 16px; text-align: center; font-weight: bold; font-size: 12pt; margin-top: 40px; }
</style>
<div class="bc">
	<table class="bc-head">
		<tr>
			<td class="side">{% if inst.logo %}<img src="{{ inst.logo | e }}" alt="">{% endif %}</td>
			<td class="bc-inst">
				<div class="n">{{ (inst.institution_name or "") | e }}</div>
				{% if inst.address %}<div class="a">{{ inst.address | e | replace("\n", ", ") }}</div>{% endif %}
				{% if c.contact_line %}<div class="c">{{ c.contact_line | e }}</div>{% endif %}
			</td>
			<td class="side"></td>
		</tr>
	</table>
	<div class="bc-rule"></div>

	{% if not doc.is_certified %}
	<div class="bc-draft">
		NOT A CERTIFICATE<br>
		Request {{ doc.name | e }} is {{ doc.status | e }}. A bonafide certificate is printed only after the request is approved.
	</div>
	{% else %}
	<table class="bc-meta">
		<tr>
			<td>Ref. No.: <b>{{ doc.certificate_number | e }}</b></td>
			<td class="r">Date: <b>{{ doc.get_formatted("issue_date") }}</b></td>
		</tr>
	</table>

	<div class="bc-title"><span>BONAFIDE CERTIFICATE</span></div>

	<div class="bc-body">
		<p>
			This is to certify that <b>{% if c.title %}{{ c.title }} {% endif %}{{ doc.student_name | e }}</b>
			<span class="nw">(Register No. <b>{{ doc.student | e }}</b>)</span>{% if c.guardian_name %}, {{ c.relation }} of {{ c.guardian_name | e }},{% endif %}
			is a bonafide student of this institution{% if c.year_words %}, studying in the {{ c.year_words }} year{% if doc.program %} of {{ doc.program | e }}{% endif %}{% elif doc.program %}, studying {{ doc.program | e }}{% endif %}{% if doc.department %}, Department of {{ doc.department | e }}{% endif %}{% if doc.academic_year %}, during the academic year {{ doc.academic_year | e }}{% endif %}.
		</p>
		<p>
			{{ c.subject }} is a resident of the institution hostel, {{ (c.hostel_name or "") | e }}{% if c.room_number %}, Room No. {{ c.room_number | e }}{% endif %}.
		</p>
		<p>
			This certificate is issued at the request of the student for {{ (c.purpose_phrase or "") | e }}
			and is valid until {{ doc.get_formatted("valid_till") }}.
		</p>
	</div>

	<table class="bc-foot">
		<tr>
			<td class="bc-qr">
				{% if doc.qr_code_data_uri %}<img src="{{ doc.qr_code_data_uri }}" alt="">{% endif %}
				<div class="t">
					Scan to verify, or visit {{ (c.verify_base_url or "") | e }} and enter the code
					<span class="code">{{ doc.verification_code | e }}</span>
				</div>
			</td>
			<td class="bc-sign">
				<div class="s">
					<div class="gap"></div>
					<div class="who">{{ (c.signatory_name or "") | e }}</div>
					<div>{{ (c.signatory_designation or "") | e }}</div>
					{% if inst.institution_short_name %}<div>{{ inst.institution_short_name | e }}</div>{% endif %}
				</div>
			</td>
		</tr>
	</table>

	<div class="bc-note">
		Certificate No. {{ doc.certificate_number | e }} &middot; Issued on {{ doc.get_formatted("issue_date") }}
		&middot; Valid till {{ doc.get_formatted("valid_till") }}<br>
		The authenticity of this certificate can be confirmed at {{ (c.verify_base_url or "") | e }}
	</div>
	{% endif %}
</div>
